        "answer": 2,
        "passage": "Few things travel across cultural boundaries as easily as food. Pizza, sushi, curry and pho are now eaten by millions of people who have never visited their countries of origin. Food is often the first aspect of a foreign culture that people try, and many develop a lasting interest in the culture through a single meal. People who have enjoyed a country's food are often more eager to visit it than <b>those</b> who have not.\n\nThe spread of cuisines usually follows the movement of people. Immigrants who open small restaurants introduce neighbours to flavours they have never tasted, and in time the dishes become part of the local menu. Cooks often adapt recipes to the ingredients and tastes of their new homes, which produces fusion dishes unknown in the original country. <u>Purists may object to such changes, but they are a natural result of cultures meeting and learning from one another.</u>\n\nFood can also create tension. Some communities feel that their traditional dishes are misrepresented when companies sell them without understanding their meaning. Others worry that local cuisines are <b>disappearing</b> as global fast-food chains spread. These concerns remind us that sharing food is not only a matter of taste but also of respect.\n\nThe best way to share food across cultures is through curiosity and respect. Learning the story behind a dish, such as who created it, on what occasion it is served and what its ingredients <b>symbolise</b>, makes eating it a richer experience. Cooking classes, food festivals and shared meals offer opportunities for exactly this kind of exchange, in which each side gives and receives."
