        "passage": "Artificial intelligence is gradually entering the classroom. Learning platforms can now analyse a student's answers, identify the topics that cause difficulty and suggest exercises that match the learner's level. Chatbots can answer questions at any hour, and translation tools help students to read materials in foreign languages. These tools promise to make learning more <b>personalised</b> than traditional lessons, in which one teacher must address dozens of students at the same time.\n\nTeachers, too, can benefit. AI can mark multiple-choice tests in seconds and prepare reports on each student's progress, which saves hours of administrative work. <u>The time that is saved can be spent on activities that machines cannot perform well, such as encouraging a discouraged student or leading a lively discussion.</u> Some teachers also use AI to generate practice questions, which they check and adjust before using them in class.\n\n[I] However, educators also see risks. [II] Students may rely on AI to complete their assignments, and so fail to develop their own thinking and writing skills. [III] AI tools can also produce information that sounds convincing but is incorrect, and learners who do not check it may be misled. [IV] In addition, the use of personal data by learning platforms raises questions about privacy.\n\nMany schools are therefore drawing up guidelines for the use of AI. These often state when AI may be used, require students to explain how they used it and encourage teachers to design assignments that test understanding rather than memorised answers. Where such rules are clear, <b>they</b> help students to treat AI as a tool for learning, not a shortcut around it."
