        "passage": "In many societies, jobs that require a university degree are respected more than jobs that involve manual skills. Parents often hope that their children will become doctors or lawyers rather than electricians or chefs. This <b>prejudice</b> has long influenced young people's choices, sometimes leading them to study subjects that they do not enjoy.\n\nYet skilled trades are essential. Without electricians, plumbers, mechanics and chefs, homes would be unsafe, vehicles would stop and restaurants would close. Skilled workers who learn through apprenticeships can start earning while still training, and they often graduate with less debt than <b>those</b> who attend university. <u>In some countries, there is a shortage of qualified tradespeople, which means that people with the right skills can find well-paid jobs quickly.</u>\n\nTechnology is changing the picture further. Modern vehicles contain advanced electronics, and kitchens use digital controls. Technicians therefore need strong knowledge of computers as well as practical skill. Many vocational schools now teach programming, data analysis and customer service alongside <b>traditional</b> crafts, and graduates are increasingly versatile.\n\nYoung people should therefore be encouraged to choose careers on the basis of interest and ability, not social prestige. Every honest occupation contributes to society, and a satisfied craftsperson is likely to be happier than an unhappy office worker. Schools can help by inviting people from different trades to describe their work and by organising visits to workshops, so that students see the full range of possibilities."
